 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');

  const parts = [];
  let i = 0;
  let literal = '';

  while (i < template.length) {
    const char = template[i];

    if (char === '{') {
      // Save any accumulated literal
      if (literal) {
        parts.push({ type: 'literal', value: literal });
        literal = '';
      }

      const braceIndex = i;
      i++;

      // Find the closing brace
      let expressionText = '';
      while (i < template.length && template[i] !== '}') {
        expressionText += template[i];
        i++;
      }

      if (i >= template.length) {
        throw new UriTemplateError(`unterminated expression at ${braceIndex}`, braceIndex);
      }

      // Now template[i] === '}'
      i++; // Skip the closing brace

      // Parse the expression
      if (expressionText === '') {
        throw new UriTemplateError(`empty expression at ${braceIndex}`, braceIndex);
      }

      // Check for operator
      let operator = '';
      let variablesText = expressionText;

      if (OPERATORS.has(expressionText[0])) {
        operator = expressionText[0];
        variablesText = expressionText.slice(1);
      } else if (RESERVED_OPERATORS.has(expressionText[0])) {
        throw new UriTemplateError(`reserved operator '${expressionText[0]}' at ${braceIndex}`, braceIndex);
      }

      // Parse variables
      const variableSpecs = variablesText.split(',');
      const variables = [];

      for (const varSpec of variableSpecs) {
        variables.push(parseVariable(varSpec, braceIndex));
      }

      parts.push({
        type: 'expression',
        operator,
        variables,
      });
    } else if (char === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    } else {
      literal += char;
      i++;
    }
  }

  // Save any remaining literal
  if (literal) {
    parts.push({ type: 'literal', value: literal });
  }

  return parts;
}"}

